// concern-seedoils-a: oil and spread cards name the seed oils to skip and a natural fat to take; avocado oil is never
// recommended; new sources come from the concern archive.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { nonEmpty } from '../../lib/testGuards.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));
const ROOT = new URL('../../../', import.meta.url).pathname;
const pre = JSON.parse(execFileSync('git', ['show', '2467f1f:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const card = (id) => { const e = kb.entries.find((x) => x.id === id); assert.ok(e, `${id} missing`); return e; };
const SKIP = new Set(['sources', 'aliases', 'asked_as', 'id', 'kind', 'category']);
const strings = (v) => (typeof v === 'string' ? [v] : Array.isArray(v) ? v.flatMap(strings) : v && typeof v === 'object' ? Object.values(v).flatMap(strings) : []);
const fields = (e) => Object.entries(e).filter(([k]) => !SKIP.has(k)).flatMap(([, v]) => strings(v));
const text = (e) => fields(e).join(' \n ');
const urlsOf = (e) => (e.sources || []).map((s) => (typeof s === 'string' ? (s.match(/https?:\S+/) || [])[0] : s.url)).filter(Boolean);

const ALL = ['cooking_oils', 'nut_butter_ingredients', 'plant_butter', 'label_cold_pressed_expeller', 'mayo', 'deli_salads', 'hummus', 'rotisserie_chicken'];

const root = join(ROOT, 'docs/sources/concerns');
const archived = new Set();
for (const d of readdirSync(root, { withFileTypes: true }).filter((x) => x.isDirectory())) {
  for (const f of readdirSync(join(root, d.name)).filter((x) => x.endsWith('.md'))) {
    const m = readFileSync(join(root, d.name, f), 'utf8').match(/^url:\s*(\S+)/m);
    if (m) archived.add(m[1]);
  }
}

test('C1 seed oil and natural fat named', () => {
  for (const id of nonEmpty(ALL, 'cards', 8)) {
    const t = text(card(id));
    assert.match(t, /seed oil|canola|sunflower|soybean|safflower|cottonseed|corn oil/i, `${id} seed oil`);
    assert.match(t, /tallow|olive|coconut|butter|ghee|lard/i, `${id} natural fat`);
  }
});

test('C2 avocado oil never recommended', () => {
  const hits = [];
  for (const id of ALL) for (const s of fields(card(id))) for (const sent of s.split(/(?<=[.;!?])\s+/)) if (/avocado/i.test(sent)) hits.push([id, sent]);
  for (const [id, sent] of hits) assert.match(sent, /skip|never|not|can carry|avoid/i, `${id}: ${sent}`);
});

test('C3 oil decisions name a natural fat', () => {
  for (const id of ['cooking_oils', 'plant_butter', 'label_cold_pressed_expeller', 'mayo']) assert.match(card(id).decision, /olive|coconut|tallow|butter/i, id);
});

test('C4 sources come from the concern archive', () => {
  nonEmpty([...archived], 'archived urls', 100);
  for (const id of ALL) {
    const before = new Set(urlsOf(pre.entries.find((x) => x.id === id)));
    const urls = nonEmpty(urlsOf(card(id)), `${id} sources`, 1);
    assert.ok(urls.some((u) => archived.has(u)), `${id} cites no concern-archive url`);
    for (const u of urls) assert.ok(before.has(u) || archived.has(u), `${id} url not archived: ${u}`);
  }
});

test('C5 no treatment or mechanism claims, no first person', () => {
  for (const id of ALL) {
    const t = text(card(id));
    assert.doesNotMatch(t, /\b(causes?|prevents?|lowers? (the )?risk|carcinogen\w*|cancer|inflam\w*|toxic\w*)\b/i, `${id} treatment`);
    assert.doesNotMatch(t, /\b(I|me|my)\b/, `${id} first person`);
  }
});
// Owns the two-line rewrite's text (docs/CARD-STYLE-SAMPLES.md): every card's decision and
// buying_tips (and egg_labels sources) equal the pin in twoLinePin.js, which older batch tests read through.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { nonEmpty } from '../../lib/testGuards.js';
import { TWO_LINE } from './twoLinePin.js';
import { matchItemToCard } from '../../lib/listMatch.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));

test('every card carries the pinned two-line decision and buying_tips', () => {
  const cards = nonEmpty(kb.entries.filter((e) => e.kind !== 'pick'), 'cards', 180);
  for (const e of cards) {
    assert.ok(TWO_LINE[e.id], `${e.id} has no two-line pin`);
    // Every pinned field, so a field the older tests restore (cart_pick, pick_steps) is still checked live.
    for (const [k, v] of Object.entries(TWO_LINE[e.id])) assert.deepEqual(e[k], v, `${e.id}.${k}`);
  }
  assert.equal(Object.keys(TWO_LINE).length, cards.length, 'a pin for a card that is gone');
});

// Known gap: lintSections L5 makes the chuck pick carry the G1 term, and that term alone outscores
// beef_cuts_basics for beef_grassfed_vs_grainfed (scorePool's top-2 window), so the pick lands uncarded.
// Pinned null so a matcher or wording change that fixes it (or sends it to the wrong card) goes red.
const KNOWN_UNCARDED = new Set(['beef_cuts_basics']);
test('every pinned cart_pick resolves to its own card on the live KB', () => {
  const ids = nonEmpty(Object.keys(TWO_LINE).filter((id) => TWO_LINE[id].cart_pick), 'pinned cart picks', 3);
  for (const id of ids) {
    const m = matchItemToCard(kb.entries.find((e) => e.id === id).cart_pick);
    assert.equal(m ? m.slug ?? m.id ?? m.entry?.id : null, KNOWN_UNCARDED.has(id) ? null : id, `${id} cart_pick`);
  }
});

// Two-line card rule check (docs/CARD-STYLE-SAMPLES.md). Usage:
//   node scripts/twoLineCheck.js [proposals.json ...]   (from server/)
// With proposals ({id: {decision, buying_tips}}), checks them applied to an in-memory KB copy;
// without, checks the KB as it stands. Exit 1 on any violation.
import { readFileSync } from 'node:fs';
import { projectEntry } from '../lib/counterCards.js';
import { lintCard, words } from '../lib/counterCardLint.js';

const kb = JSON.parse(readFileSync(new URL('../kristy_perimeter_kb.json', import.meta.url)));
const doLines = JSON.parse(readFileSync(new URL('../lib/doLines.json', import.meta.url)));
const doFor = (id) => (Array.isArray(doLines) ? doLines.find((d) => d.slug === id || d.id === id)?.do : doLines[id]?.do ?? doLines[id]) || '';
const proposals = Object.assign({}, ...process.argv.slice(2).map((f) => JSON.parse(readFileSync(f, 'utf8'))));
const byId = new Map(kb.entries.map((e) => [e.id, e]));
const FIRST_PERSON = /\b(I|me|my|mine|we|our|us)\b/;
const APPROVED_LONG = new Set(['ground_beef_lean_ratio', 'whole_vs_reduced_fat_milk']);
let bad = 0;
const ids = Object.keys(proposals).length ? Object.keys(proposals) : kb.entries.filter((e) => e.kind !== 'pick').map((e) => e.id);
for (const id of ids) {
  const base = byId.get(id);
  if (!base) { console.log(`${id}: NO_SUCH_ENTRY`); bad++; continue; }
  const e = { ...base, ...(proposals[id] || {}) };
  const out = [];
  const tip0 = (e.buying_tips || [])[0] || '';
  // Devon approved the CARD-STYLE-SAMPLES line 1s verbatim (2026-10-17); "10 words plus the food" lets ground beef run 12.
  if (words(e.decision) > (APPROVED_LONG.has(id) ? 12 : 10)) out.push(`LINE1_LONG ${words(e.decision)}w`);
  const card = projectEntry(e, { doLine: doFor(id) });
  if (card.look_for?.[0] !== tip0) out.push(`LINE2_NOT_FIRST_LOOK_FOR (cautionary wording or authored watch_out?)`);
  if (tip0.length > 90) out.push(`LINE2_LONG ${tip0.length}c`);
  for (const [f, v] of [['decision', e.decision], ['tip0', tip0]]) if (FIRST_PERSON.test(v)) out.push(`FIRST_PERSON ${f}`);
  if (/—/.test(e.decision) || /—/.test(tip0)) out.push('EM_DASH');
  for (const v of lintCard(card) || []) out.push(`${v.code}${v.field ? `[${v.field}]` : ''} ${v.detail || ''}`.trim());
  if (out.length) { bad++; console.log(`${id}: ${out.join(' | ')}`); }
}
console.log(`${ids.length} checked, ${bad} with violations`);
process.exit(bad ? 1 : 0);
