// Generate server/lib/doLines.json from docs/do-lines-review.md.
//
//   node scripts/buildDoLines.js
//
// WHY THIS FILE EXISTS: THE DEPLOY BOUNDARY. Railway's Root Directory is `server/`, so
// nothing outside it reaches production. Both the counter's card projection and its ask
// pipeline read the reviewed `do` lines from `docs/`, wrapped in a try/catch that fell
// back to an empty Map — so in production every curated card served by /api/counter/ask
// had an EMPTY do line. The do line is the whole point of the card, and asking is the
// lead interaction on the Counter. It had been that way since the lines were authored.
//
// The markdown stays the AUTHORED SOURCE, because it is reviewed by hand and its table
// is the reviewable artifact. This JSON is a build product of it that lives inside the
// deploy boundary, and `doLines.test.js` fails if the two disagree — so the generated
// file cannot drift from the reviewed one.
//
// Run this after editing the review table, and commit the result.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { parseReviewTable } from '../lib/counterCards.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REVIEW = join(__dirname, '..', '..', 'docs', 'do-lines-review.md');
const OUT = join(__dirname, '..', 'lib', 'doLines.json');

const reviewed = parseReviewTable(readFileSync(REVIEW, 'utf8'));
if (!reviewed.size) {
  console.error('[do-lines] the review table parsed to nothing — refusing to write an empty file.');
  process.exit(1);
}

// Slug -> do line. The `flag` column is review metadata and is deliberately not carried:
// production needs the line, not the notes about drafting it.
const out = {};
for (const slug of [...reviewed.keys()].sort()) {
  const line = String(reviewed.get(slug)?.do || '').trim();
  if (line) out[slug] = line;
}

writeFileSync(OUT, `${JSON.stringify(out, null, 2)}\n`, 'utf8');
console.log(`[do-lines] wrote ${Object.keys(out).length} do lines to lib/doLines.json ✓`);
// doLines.json is a BUILD PRODUCT of docs/do-lines-review.md, and this test is the only
// thing holding them together.
//
// The markdown is the authored source: it is reviewed by hand, it carries the drafting
// notes, and its table is what a person edits. The JSON exists solely because the markdown
// lives outside the deploy boundary (`server/`), so production never sees it — which is
// how every curated card on /api/counter/ask came to carry an empty do line.
//
// A generated file that nothing checks is a file that drifts. Edit the table, run
// `node scripts/buildDoLines.js`, commit both.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { nonEmpty } from './testGuards.js';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import perimeterKb from '../kristy_perimeter_kb.json' with { type: 'json' };
import doLines from './doLines.json' with { type: 'json' };
import { parseReviewTable, RETIRED } from './counterCards.js';
import { questionEntries } from './perimeter.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const reviewed = nonEmpty(
  parseReviewTable(readFileSync(join(__dirname, '..', '..', 'docs', 'do-lines-review.md'), 'utf8')),
  'the reviewed do-line table'
);

test('doLines.json agrees with the reviewed markdown, exactly', () => {
  const fromMarkdown = {};
  for (const [slug, row] of reviewed) {
    const line = String(row?.do || '').trim();
    if (line) fromMarkdown[slug] = line;
  }
  assert.deepEqual(
    doLines,
    fromMarkdown,
    'lib/doLines.json is stale — run `node scripts/buildDoLines.js` and commit the result'
  );
});

test('every authored entry has a do line, and no retired one does', () => {
  // The do line is the field the card exists to carry, so a missing one is not a gap in
  // a build product — it is a card with no action on it.
  for (const e of nonEmpty(questionEntries(perimeterKb.entries), 'questionEntries')) {
    assert.ok(doLines[e.id], `${e.id} has no do line in doLines.json`);
  }
  for (const slug of nonEmpty(RETIRED, 'RETIRED')) {
    assert.ok(!doLines[slug], `${slug} is retired but still carries a do line`);
  }
});

test('the do lines survive the deploy boundary', () => {
  // The regression, stated as behaviour. Both consumers must resolve their do lines from
  // inside server/ — if either goes back to reading docs/, this fails wherever docs/ is
  // absent, which is exactly where it matters and nowhere a local test would notice.
  for (const file of ['counterCards.js', 'counterAskPipeline.js']) {
    const src = readFileSync(join(__dirname, file), 'utf8');
    assert.ok(
      !/\.\.\/\.\.\/docs/.test(src),
      `${file} reads docs/ again — that path does not exist in production`
    );
    assert.ok(/doLines\.json/.test(src), `${file} no longer reads doLines.json`);
  }
});
